        Order order = new Order();
        order.setId(123L);
        order.setCustomerName("Craig");
        order.setOrderDate(now());
        List<Order> orderList = new ArrayList<>();
        orderList.add(order);
        return orderList;
    }

    private boolean credentialMatch(String credValue) {
        //logic to check credValue
        return true;
    }
}

